/* Ninja Penguins v106: synchronized release, high toss, upward axial spin. */
(function(root){"use strict";
const C=x=>Math.max(0,Math.min(1,x)),L=(a,b,t)=>a+(b-a)*t,E=t=>t*t*(3-2*t),TAU=Math.PI*2;
const HIT=[.62,.64,.66],FLIGHT=.018,GROUND=432,HOME=500,atlas=new Image(),listeners=[];
let ready=false;
atlas.onload=()=>{ready=true;for(const fn of listeners)fn();};
atlas.src="data:image/png;base64,";
const local=(p,a,b)=>C((p-a)/(b-a));
function frameAt(p){
 if(p<.20)return Math.min(5,Math.floor(local(p,0,.20)*12)%6);
 if(p<.30)return 6;
 if(p<.40)return 7+Math.min(4,Math.floor(local(p,.30,.40)*5));
 if(p<.57)return p<.46?4:12;
 if(p<.70){
  const roll=Math.floor(local(p,.57,.70)*36)%6;
  return (HIT.some(t=>p>=t-FLIGHT-.005&&p<=t+.005)?18:12)+roll;
 }
 if(p<.78)return p<.755?24:25;
 if(p<.88)return 27+Math.min(2,Math.floor(local(p,.78,.88)*3));
 if(p<.94)return 30+Math.min(2,Math.floor(local(p,.88,.94)*3));
 return 33+Math.min(2,Math.floor(local(p,.94,1)*3));
}
function pose(p,index,target){
 const dir=target.x>=HOME?1:-1,home=HOME+(index-1)*65;
 const apex={x:target.x-dir*170,y:Math.max(100,Math.min(165,target.y-330))};
 const landing={x:target.x-dir*120,y:target.y-48};
 let x=home,y=GROUND-48,angle=0,frame=30,alpha=1,depth=GROUND,facing=dir;
 if(p<.20){
  const start=index*.024,q=local(p,start,start+.15),e=E(q);
  x=L(home-dir*(360+index*30),home,e);
  y=GROUND-48-(1-q)*(150+index*32)-Math.sin(q*Math.PI)*(75+index*15);
  frame=q>=1?5:Math.floor(q*12)%6;alpha=p<start?0:C(q*12);
 }else if(p<.30){
  const q=E(local(p,.20,.30));
  x=L(home,index===2?HOME:HOME+(index===0?-40:40),q);
  if(index===2){y=GROUND-48-Math.sin(q*Math.PI)*70-q*52;frame=0;}
  else {frame=6;facing=index===0?1:-1;}
 }else if(p<.38){
  x=index===2?HOME:HOME+(index===0?-40:40);
  const q=local(p,.30,.38);
  // The rider stays on their flippers until the shared release beat.
  if(index===2){y=GROUND-100-E(q)*12;frame=0;}
  else{frame=7+Math.min(3,Math.floor(q*4));facing=index===0?1:-1;}
 }else if(index===2&&p<.57){
  // Lift-off coincides exactly with both throwers' extended release pose.
  const q=local(p,.38,.57),rise=1-(1-q)*(1-q);
  x=L(HOME,apex.x,E(q));y=L(GROUND-112,apex.y,rise);
  frame=p<.46?4:12;depth=L(GROUND,target.y,E(q));
  angle=-Math.PI/4*dir*E(local(p,.38,.46));
 }else if(index===2&&p<.70){
  x=apex.x;y=apex.y;frame=frameAt(p);depth=target.y;
  // Head points skyward toward the opposing side; kunai aim independently.
  angle=-Math.PI/4*dir;
 }else if(index===2&&p<.78){
  const q=local(p,.70,.78);x=landing.x;y=L(apex.y,landing.y,q*q);
  frame=q<.65?24:25;depth=target.y;
 }else if(index===2&&p<.88){
  const q=local(p,.78,.88);x=L(landing.x,home,E(q));
  y=L(landing.y,GROUND-48,E(q))-Math.sin(q*Math.PI)*100;
  frame=q<.15?27:q<.85?28:29;depth=L(target.y,GROUND,E(q));
 }else if(p>=.38&&p<.88){
  x=L(HOME+(index===0?-40:40),home,E(local(p,.82,.88)));frame=p<.46?11:30;
 }else if(p>=.88){frame=frameAt(p);}
 return {x,y,dir:facing,angle,frame,alpha,ground:depth,depth,index};
}
function cell(c,frame,x,y,width,dir=1,angle=0,alpha=1){
 if(!ready||alpha<=0)return;
 const sw=atlas.naturalWidth/6,sh=atlas.naturalHeight/6,h=width*sh/sw;
 c.save();c.globalAlpha*=alpha;c.translate(x,y);c.rotate(angle);c.scale(dir,1);
 c.drawImage(atlas,frame%6*sw,Math.floor(frame/6)*sh,sw,sh,-width/2,-h/2,width,h);c.restore();
}
function shot(p,index,target){
 const release=HIT[index]-FLIGHT,a=pose(release,2,target);
 const end={x:target.x,y:target.y-65},heading=Math.atan2(end.y-a.y,end.x-a.x);
 const origin={x:a.x+Math.cos(heading)*45,y:a.y+Math.sin(heading)*45},q=local(p,release,HIT[index]);
 return {x:L(origin.x,end.x,q),y:L(origin.y,end.y,q),origin,end,q,release,angle:heading};
}
function depthFor({target,progress=0},layer){
 if(layer==="ground")return 200;
 if(layer==="impact"||layer==="kunai")return target.y+.2;
 if(layer==="actor2")return pose(progress,2,target).depth;
 return GROUND;
}
function draw(c,{progress:p,target,layer}){
 if(!target)return;p=C(p);
 if(layer==="ground"&&p<.94){
  for(let i=0;i<3;i++){const a=pose(p,i,target);c.save();c.globalAlpha*=.18*a.alpha;c.fillStyle="#102633";
   c.beginPath();c.ellipse(a.x,a.ground,27,7,0,0,TAU);c.fill();c.restore();}return;
 }
 if(layer.startsWith("actor")){
  const i=Number(layer.slice(5));
  if(!Number.isInteger(i)||i<0||i>2)return;
  if(p<.94){const a=pose(p,i,target);cell(c,a.frame,a.x,a.y,126,a.dir,a.angle,a.alpha);}
  else if(i===0){cell(c,frameAt(p),HOME,GROUND-50,L(260,350,local(p,.94,1)));}
  return;
 }
 for(let i=0;i<3;i++){
  const s=shot(p,i,target);
  if(layer==="kunai"&&p>=s.release&&p<HIT[i]){
   c.save();c.strokeStyle="#c8faff";c.shadowColor="#70dcff";c.shadowBlur=10;c.lineWidth=3;
   c.beginPath();c.moveTo(L(s.origin.x,s.x,.25),L(s.origin.y,s.y,.25));c.lineTo(s.x,s.y);c.stroke();
   c.translate(s.x,s.y);c.rotate(s.angle);c.fillStyle="#b8f5ff";c.beginPath();c.moveTo(25,0);c.lineTo(0,-6);c.lineTo(-12,0);c.lineTo(0,6);c.closePath();c.fill();c.restore();
  }
  const q=(p-HIT[i])/.035;
  if(layer==="impact"&&q>=0&&q<1){
   c.save();c.translate(s.end.x,s.end.y);c.globalAlpha*=1-q;c.strokeStyle="#c0f5ff";c.lineWidth=3;
   c.beginPath();c.arc(0,0,6+q*34,0,TAU);c.stroke();
   for(let j=0;j<9;j++){const a=j*TAU/9+i,r=8+q*45;c.beginPath();c.moveTo(Math.cos(a)*r,Math.sin(a)*r);c.lineTo(Math.cos(a)*(r+14),Math.sin(a)*(r+14));c.stroke();}c.restore();
  }
 }
}
function portrait(c,w,h){
 for(let i=0;i<3;i++)cell(c,30,w*(.25+i*.25),h*.52,Math.min(w*.45,h*.9),i===2?-1:1);
}
root.WIZARDRY_PENGUINS_V103={draw,pose,frameAt,shot,depthFor,portrait,timing:{hits:HIT,flight:FLIGHT},onReady:fn=>{listeners.push(fn);if(ready)fn();}};
})(window);
